import hashlib, html, json, re, sys
from pathlib import Path
source, extraction, call, funding, form, controls, milestone, output = map(Path, sys.argv[1:])
def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()
captured = json.loads(extraction.read_text())
assert digest(source) == captured['source_sha256']
def normalize(text):
    return ' '.join(html.unescape(re.sub(r'<[^>]+>', '', text)).split())
policy = normalize(source.read_text())
quotes = {item['line']: item['text'] for item in captured['passages'] if item['line'] in (42,45,48,49,50,52,53,54,55,67)}
assert all(normalize(quotes[n]) in policy for n in (48,50,52,53))
def policy_links(path):
    return sorted(set(re.findall(r'href="([^"]*generativeAI[^"]*)"', path.read_text(), re.I)))
decision = {
    'disposition': 'Do not submit the autonomous AI workflow under policy 2.0. Preserve the executed CSV milestone for other outlets.',
    'policy_url': captured['source_url'],
    'source_hashes': {str(path): digest(path) for path in (source,call,funding,form,controls,milestone)},
    'call_material_policy_links': {str(path): policy_links(path) for path in (call,funding,form)},
    'policy_quotes': quotes,
    'applicability': 'The published policy expressly covers proposals submitted to NLnet and funded artifacts. It refers to an NGI Zero transition FAQ. No exception for this proposed workflow was established by this assessment.',
    'reopen': 'First-party call-specific terms expressly permitting this workflow, or a separately evidenced eligible human-led application and delivery plan complying with the operative policy and disclosing existing AI-generated code as required.',
    'executed_controls': str(controls),
    'reusable_milestone': str(milestone),
    'submission': 'none', 'award': 'unverified', 'settlement': 'unverified'
}
output.write_text(json.dumps(decision,indent=2,ensure_ascii=False)+'\n')
print(json.dumps(decision['call_material_policy_links']))
